&lt;p&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 14.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-size: 12pt;&quot;&gt;Join VitalCaring – Where Your Passion Changes Lives!&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-size: 12pt;&quot;&gt;Speech Language Pathologist (SLP) – Home Health&lt;/span&gt;&lt;/p&gt;
